// Service Health Monitor — Docker Engine API via Unix socket
// Checks all containers, restarts unhealthy/exited/dead, logs to DB
const http = require('http');

const MONITORED = [
  'sovereign-stack-postgres-1',
  'sovereign-stack-redis-1',
  'sovereign-stack-minio-1',
  'sovereign-stack-cloudflared-1',
  'sovereign-stack-landing-1',
  'sovereign-stack-searxng-1',
  'sovereign-stack-qdrant-1',
  'sovereign-stack-uptime-kuma-1',
  'sovereign-stack-ollama-1',
  'sovereign-stack-litellm-1',
  'sovereign-stack-langfuse-1',
  'sovereign-stack-authentik-server-1',
  'sovereign-stack-authentik-worker-1',
  'sovereign-stack-outline-1',
];

const RESTART_COOLDOWN_MS = 5 * 60 * 1000;

function dockerRequest(method, path, body) {
  return new Promise((resolve, reject) => {
    const options = {
      socketPath: '/var/run/docker.sock',
      path: '/v1.41' + path,
      method: method,
      headers: { 'Content-Type': 'application/json' }
    };
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        try {
          resolve({ status: res.statusCode, data: data ? JSON.parse(data) : null });
        } catch (e) {
          resolve({ status: res.statusCode, data: data });
        }
      });
    });
    req.on('error', reject);
    req.setTimeout(15000, () => { req.destroy(); reject(new Error('timeout')); });
    if (body) req.write(JSON.stringify(body));
    req.end();
  });
}

function dockerRequestRaw(method, path) {
  return new Promise((resolve, reject) => {
    const options = {
      socketPath: '/var/run/docker.sock',
      path: '/v1.41' + path,
      method: method
    };
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => resolve({ status: res.statusCode, data: data }));
    });
    req.on('error', reject);
    req.setTimeout(15000, () => { req.destroy(); reject(new Error('timeout')); });
    req.end();
  });
}

function dbQuery(sql) {
  return new Promise(async (resolve, reject) => {
    try {
      const createExec = await dockerRequest('POST', '/containers/sovereign-stack-postgres-1/exec', {
        Cmd: ['sh', '-c', `PGPASSWORD=$POSTGRES_PASSWORD psql -U sovereign -d gilbert -c "${sql.replace(/"/g, '\\"')}"`],
        AttachStdout: true,
        AttachStderr: true
      });
      if (createExec.status !== 201 || !createExec.data || !createExec.data.Id) {
        return reject(new Error('Failed to create exec'));
      }
      const startExec = await dockerRequestRaw('POST', '/exec/' + createExec.data.Id + '/start');
      resolve(startExec);
    } catch (e) {
      reject(e);
    }
  });
}

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

function friendlyName(containerName) {
  return containerName.replace('sovereign-stack-', '').replace(/-1$/, '');
}

async function checkAndRecover() {
  const incidents = [];

  for (const name of MONITORED) {
    try {
      const inspect = await dockerRequest('GET', '/containers/' + name + '/json');
      if (inspect.status === 404) continue;
      if (inspect.status !== 200 || !inspect.data) continue;

      const info = inspect.data;
      const state = info.State;
      const containerStatus = state.Status;
      const healthStatus = state.Health ? state.Health.Status : null;
      const oomKilled = state.OOMKilled || false;
      const exitCode = state.ExitCode;
      const startedAt = new Date(state.StartedAt);
      const restartCount = info.RestartCount || 0;
      const containerId = info.Id ? info.Id.substring(0, 12) : '';

      let needsAction = false;
      let incidentType = '';
      let severity = 'warning';

      if (containerStatus === 'exited' || containerStatus === 'dead') {
        needsAction = true;
        incidentType = containerStatus;
        severity = 'critical';
      } else if (healthStatus === 'unhealthy') {
        needsAction = true;
        incidentType = 'unhealthy';
        severity = 'warning';
      }

      if (oomKilled) {
        incidentType = 'oom_killed';
        severity = 'critical';
      }

      if (!needsAction) continue;

      const msSinceStart = Date.now() - startedAt.getTime();
      if (msSinceStart < RESTART_COOLDOWN_MS && containerStatus === 'running') {
        const diag = {
          container_state: containerStatus,
          health_status: healthStatus,
          oom_killed: oomKilled,
          exit_code: exitCode,
          restart_count: restartCount,
          started_at: state.StartedAt,
          cooldown_remaining_s: Math.round((RESTART_COOLDOWN_MS - msSinceStart) / 1000)
        };
        if (state.Health && state.Health.Log && state.Health.Log.length > 0) {
          diag.health_log = state.Health.Log.slice(-3).map(l => ({
            exit_code: l.ExitCode,
            output: (l.Output || '').substring(0, 200),
            start: l.Start
          }));
        }
        incidents.push({
          service_name: friendlyName(name),
          incident_type: 'restart_loop',
          severity: 'critical',
          container_id: containerId,
          diagnostics: diag,
          action_taken: 'skipped (cooldown)',
          action_result: 'skipped'
        });
        continue;
      }

      const diag = {
        container_state: containerStatus,
        health_status: healthStatus,
        oom_killed: oomKilled,
        exit_code: exitCode,
        restart_count: restartCount,
        started_at: state.StartedAt
      };

      if (containerStatus === 'running') {
        try {
          const stats = await dockerRequest('GET', '/containers/' + name + '/stats?stream=false');
          if (stats.status === 200 && stats.data && stats.data.memory_stats) {
            const memUsage = stats.data.memory_stats.usage || 0;
            const memLimit = stats.data.memory_stats.limit || 0;
            diag.mem_usage_mb = Math.round(memUsage / 1024 / 1024);
            diag.mem_limit_mb = Math.round(memLimit / 1024 / 1024);
            if (memLimit > 0) diag.mem_pct = Math.round((memUsage / memLimit) * 100);
          }
        } catch (e) { /* stats failed */ }
      }

      if (state.Health && state.Health.Log && state.Health.Log.length > 0) {
        diag.health_log = state.Health.Log.slice(-3).map(l => ({
          exit_code: l.ExitCode,
          output: (l.Output || '').substring(0, 200),
          start: l.Start
        }));
      }

      let actionTaken = 'restart';
      let actionResult = 'failure';

      try {
        const restart = await dockerRequest('POST', '/containers/' + name + '/restart?t=30');
        if (restart.status === 204) {
          await sleep(30000);
          const postInspect = await dockerRequest('GET', '/containers/' + name + '/json');
          if (postInspect.status === 200 && postInspect.data) {
            const postState = postInspect.data.State;
            diag.post_restart_state = postState.Status;
            diag.post_restart_health = postState.Health ? postState.Health.Status : 'no_healthcheck';
            if (postState.Status === 'running' && (!postState.Health || postState.Health.Status !== 'unhealthy')) {
              actionResult = 'success';
            }
          }
        }
      } catch (e) {
        diag.restart_error = e.message;
      }

      if (actionResult === 'failure') {
        actionTaken = 'restart (failed)';
        incidentType = 'restart_failed';
        severity = 'critical';
        try {
          const logs = await dockerRequestRaw('GET', '/containers/' + name + '/logs?stdout=true&stderr=true&tail=30&timestamps=true');
          if (logs.status === 200 && logs.data) {
            const rawLines = logs.data.split('\n');
            const cleanLines = rawLines.map(line => line.length > 8 ? line.substring(8) : line).filter(l => l.trim().length > 0);
            diag.last_logs = cleanLines.slice(-30).join('\n').substring(0, 2000);
          }
        } catch (e) { /* logs failed */ }
      }

      incidents.push({
        service_name: friendlyName(name),
        incident_type: incidentType,
        severity: severity,
        container_id: containerId,
        diagnostics: diag,
        action_taken: actionTaken,
        action_result: actionResult
      });

    } catch (e) {
      incidents.push({
        service_name: friendlyName(name),
        incident_type: 'dead',
        severity: 'critical',
        container_id: '',
        diagnostics: { error: e.message },
        action_taken: 'inspect failed',
        action_result: 'failure'
      });
    }
  }

  // Log incidents to DB
  if (incidents.length > 0) {
    for (const inc of incidents) {
      try {
        const diagJson = JSON.stringify(inc.diagnostics).replace(/'/g, "''");
        const svcName = inc.service_name.replace(/'/g, "''");
        const actTaken = (inc.action_taken || '').replace(/'/g, "''");
        const resolved = inc.action_result === 'success' ? 'true' : 'false';
        const resolvedAt = inc.action_result === 'success' ? 'now()' : 'NULL';
        const sql = "INSERT INTO service_incidents (service_name, incident_type, severity, container_id, diagnostics, action_taken, action_result, resolved, created_at, resolved_at) VALUES ('" + svcName + "', '" + inc.incident_type + "', '" + inc.severity + "', '" + inc.container_id + "', '" + diagJson + "'::jsonb, '" + actTaken + "', '" + inc.action_result + "', " + resolved + ", now(), " + resolvedAt + ");";
        await dbQuery(sql);
      } catch (e) { /* DB logging failed — non-fatal */ }
    }
  }

  // Build email message for downstream emailSend node
  let message = '';
  let subject = '';
  if (incidents.length > 0) {
    const hasCritical = incidents.some(i => i.severity === 'critical');
    const allRecovered = incidents.every(i => i.action_result === 'success');
    subject = 'Health Monitor: ' + incidents.length + ' incident(s)' + (hasCritical ? ' [CRITICAL]' : '') + (allRecovered ? ' [recovered]' : '');

    message = '<html><body>';
    message += '<h2>Service Health Monitor</h2>';
    message += '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;">';
    message += '<tr><th>Service</th><th>Issue</th><th>Result</th><th>Details</th></tr>';
    for (const inc of incidents) {
      const icon = inc.action_result === 'success' ? '\u2705' : (inc.severity === 'critical' ? '\ud83d\udd34' : '\u26a0\ufe0f');
      let result = '';
      if (inc.action_result === 'success') {
        result = 'Restarted OK';
        if (inc.diagnostics.post_restart_health) result += ' (' + inc.diagnostics.post_restart_health + ')';
      } else if (inc.action_result === 'skipped') {
        result = 'Cooldown (' + inc.diagnostics.cooldown_remaining_s + 's remaining)';
      } else {
        result = 'RESTART FAILED';
      }
      let details = '';
      if (inc.diagnostics.mem_pct) {
        details += 'Memory: ' + inc.diagnostics.mem_usage_mb + 'MB/' + inc.diagnostics.mem_limit_mb + 'MB (' + inc.diagnostics.mem_pct + '%)<br>';
      }
      if (inc.diagnostics.oom_killed) details += 'OOM Killed<br>';
      if (inc.diagnostics.exit_code && inc.diagnostics.exit_code !== 0) details += 'Exit code: ' + inc.diagnostics.exit_code + '<br>';
      message += '<tr><td>' + icon + ' ' + inc.service_name + '</td><td>' + inc.incident_type + '</td><td>' + result + '</td><td>' + (details || '-') + '</td></tr>';
    }
    message += '</table>';
    message += '<p><em>' + new Date().toISOString().substring(0, 19) + 'Z</em></p>';
    message += '</body></html>';
  }

  return [{
    json: {
      has_incidents: incidents.length > 0,
      incident_count: incidents.length,
      message: message,
      subject: subject,
      incidents: incidents.map(i => i.service_name + ':' + i.incident_type + ':' + i.action_result)
    }
  }];
}

return await checkAndRecover();
